const $=id=>document.getElementById(id),slots=[0,1,2,3,5,6,7,8],colors=['#83cab2','#b89edb','#83b7de','#a4bdcf','#d6aa95','#c8b879','#a4a6d8','#d0a6ba'];
const uid=()=>crypto.randomUUID(),today=(()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;})();
const state={version:2,title:'',period:'',areas:[],tasks:[{id:'task-demo',title:'Подготовить подборку работ',status:'todo',date:today},{id:'task-second',title:'Обсудить идею с другом',status:'doing',date:''}],habits:[{id:'habit-demo',title:'15 минут творческой практики',history:{}}]};
let mode='goal',tab='matrix',view='home',areaIndex=0,selected={kind:'goal'},editingTask=null;
const makeCard=()=>({id:uid(),kind:'result',title:'',description:'',status:'idea',checklist:[],notes:[],taskIds:[],habitIds:[],icon:'◇',cover:'soft'});
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn,cls){const b=el('button',text,cls);b.type='button';b.onclick=fn;return b;}
function field(label,input){const l=el('label',label);l.append(input);return l;}
function input(value='',placeholder=''){const n=el('input');n.value=value;n.placeholder=placeholder;n.maxLength=120;return n;}
function select(options,value){const s=el('select');for(const [v,t] of options){const o=el('option',t);o.value=v;s.append(o);}s.value=value;return s;}
const statuses=[['idea','Не начато'],['focus','В фокусе'],['doing','В процессе'],['pause','На паузе'],['done','Завершено']];
function notice(s){$('notice').textContent=s;}function current(){const area=state.areas[selected.a];return selected.archiveId?(area?.storedCards||[]).find(c=>c.id===selected.archiveId):area?.cards[selected.k];}
function linkedCards(taskId){return state.areas.flatMap(a=>[...a.cards,...(a.storedCards||[])].filter(c=>c.taskIds.includes(taskId)).map(c=>({a,c})));}
const presets={life:['Здоровье','Работа','Финансы','Отношения','Развитие','Дом','Отдых','Творчество'],goal:['Навыки','Ресурсы','Практика','Поддержка','','','',''],blank:Array(8).fill(''),task:['Подготовка','Материалы','Обратная связь','','','','','']};
for(const [m,title,desc] of [['life','Собрать картину жизни','Редактируемые направления — оставь только свои.'],['goal','Дойти до одной цели','Подумай, что поможет её осуществить.'],['blank','Собрать свою структуру','Без предложенных названий и категорий.'],['task','Начать с карточки на доске','Попробовать на вымышленной карточке «Подготовить подборку работ».']]){$('choices').append(button('',()=>{mode=m;document.querySelectorAll('.choice').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));$('setup').hidden=false;$('mainTitle').value=m==='life'?'Моя карта жизни':m==='task'?state.tasks[0].title:'';$('areaInputs').replaceChildren();presets[m].forEach((v,i)=>{$('areaInputs').append(field(`Направление ${i+1} · необязательно`,input(v)));});$('mainTitle').focus();},'choice'));const b=$('choices').lastChild;b.dataset.mode=m;b.append(el('strong',title),el('span',desc));}
$('setup').onsubmit=e=>{e.preventDefault();const title=$('mainTitle').value.trim();if(!title)return;state.title=title;state.period=$('period').value.trim();state.areas=[...$('areaInputs').querySelectorAll('input')].map((n,i)=>({id:uid(),title:n.value.trim(),description:'',color:colors[i],cards:Array.from({length:8},makeCard)}));if(mode==='task'){state.areas[0].cards[0].title=state.tasks[0].title;state.areas[0].cards[0].taskIds.push(state.tasks[0].id);}$('onboarding').hidden=true;$('app').hidden=false;render();};
for(const [id,title] of [['matrix','Матрица'],['board','Доска'],['habits','Привычки'],['calendar','Календарь']]){const b=button(title,()=>{tab=id;render();});b.dataset.tab=id;$('tabs').append(b);}
$('home').onclick=()=>{view='home';selected={kind:'goal'};render();};$('overview').onclick=()=>{view='all';render();};
function render(){rememberPanel();document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false'));$('matrixTools').hidden=true;$('heading').textContent=tab==='matrix'?state.title:({board:'Те же задачи на доске',habits:'Практика, которая поддерживает цель',calendar:'Даты связанных дел'})[tab];$('crumb').textContent=tab==='matrix'?(view==='area'?`МАТРИЦА / ${state.areas[areaIndex].title||'Направление'}`:'ТВОЯ КАРТА'):'ДЕМОНСТРАЦИЯ · ОБЩИЕ ДАННЫЕ';renderCrumbs();$('home').hidden=true;$('overview').textContent='Обзор 9×9';$('overview').setAttribute('aria-pressed',String(view==='all'));$('content').replaceChildren();if(tab==='matrix')renderMatrix();if(tab==='board')renderBoard();if(tab==='habits')renderHabits();if(tab==='calendar')renderCalendar();}
function choose(kind,a,k){selected={kind,a,k};render();}
function tile(text,cls,fn,color,sub){const b=button('',fn,'cell '+cls);b.style.setProperty('--accent',color||'#baa0df');b.title=[text||'Добавить',sub].filter(Boolean).join(' · ');b.setAttribute('aria-label',b.title);b.append(el('span',text||'+'));if(sub){b.append(el('small',sub));const count=sub.match(/(\d+) задач/);if(count)b.append(el('em','☑ '+count[1],'miniTaskCount'));}return b;}
function renderMatrix(){
 const layout=el('div',undefined,'functionalLayout'),canvas=el('section',undefined,'canvas'),g=el('div');g.id='matrix';
 if(view==='all')g.className='overview';
 const controls=el('div',undefined,'mapControls');
 const zoom=button(view==='all'?'⊞ Крупнее':'⊞ Вся карта',()=>travel(view==='all'?'home':'all'), 'mapZoom');zoom.setAttribute('aria-pressed',String(view==='all'));
 controls.append(zoom);canvas.append(controls,g);
 function direction(parent,a,center=false){
  const d=state.areas[a],wrap=el('div',undefined,'directionTile');
  const b=tile(d.title,center?'center':d.title?'direction':'empty',()=>{
   if(!d.title){editSelection('area',a);return;}
   travel(view==='area'&&areaIndex===a?'home':'area',a);
  },d.color,center&&view==='area'?'Свернуть':undefined);
  b.dataset.area=a;b.setAttribute('aria-expanded',String(view==='area'&&areaIndex===a));
  wrap.append(b);
  const edit=button('✎',()=>editSelection('area',a),'tileEdit');edit.setAttribute('aria-label','Редактировать направление '+(d.title||a+1));wrap.append(edit);parent.append(wrap);
 }
 function group(parent,a){for(let j=0;j<9;j++){const k=slots.indexOf(j);
  if(a===null){if(j===4){const b=tile(state.title,'center',()=>editSelection('goal'),null,state.period);parent.append(b);}else direction(parent,k);}
  else{const d=state.areas[a];if(j===4)direction(parent,a,true);else{const c=d.cards[k];parent.append(tile(c.title,(c.title?'':'empty')+(c.status==='done'?' done':''),()=>{if(!d.title)editSelection('area',a);else choose('card',a,k);},d.color,c.title?cardSummary(c):''));}}
 }}
 if(view==='all'){for(let j=0;j<9;j++){const p=el('div',undefined,'group');group(p,j===4?null:slots.indexOf(j));g.append(p);}}else group(g,view==='home'?null:areaIndex);
 if(view==='area'){
  const rail=el('div',undefined,'directionRail');rail.setAttribute('aria-label','Другие направления');
  state.areas.forEach((d,i)=>{if(d.title){const b=button(d.title,()=>travel(i===areaIndex?'home':'area',i));b.style.setProperty('--accent',d.color);b.setAttribute('aria-pressed',String(i===areaIndex));rail.append(b);}});canvas.append(rail);
 }
 layout.append(canvas,compactEditor(renderEditor()));$('content').append(layout);decorateMatrix();attachBloom();
}
function renderEditor(){const aside=el('aside'),body=el('div',undefined,'cardBody'),s=selected,d=state.areas[s.a],c=s.kind==='card'?current():null;aside.style.setProperty('--accent',d?.color||'#baa0df');if(c&&c.cover!=='none')aside.append(el('div',undefined,'cover'));aside.append(body);body.append(el('p',s.kind==='card'?'КАРТОЧКА ЦЕЛИ':s.kind==='area'?'НАПРАВЛЕНИЕ':'ГЛАВНАЯ ЦЕЛЬ','eyebrow'),el('h2',c?.title||d?.title||(s.kind==='goal'?'К чему ты идёшь?':'Начни с названия')));const form=el('form'),title=input(c?c.title:d?d.title:state.title),desc=el('textarea');title.required=true;title.dataset.test='title';desc.maxLength=2000;desc.rows=3;desc.value=c?.description||d?.description||'';form.append(field('Название',title));if(s.kind!=='goal')form.append(field('Зачем / описание',desc));let color,stat,icon,cover,period,kind;if(s.kind==='goal'){period=input(state.period);form.append(field('Горизонт',period));}if(s.kind==='area'){color=input(d.color);color.type='color';form.append(field('Цвет направления',color));}if(c){kind=select([['result','Результат'],['practice','Постоянная практика']],c.kind||'result');kind.dataset.test='kind';stat=select(statuses.filter(x=>c.kind!=='practice'||x[0]!=='done'),c.status);kind.onchange=()=>{const previous=stat.value;stat.replaceChildren(...select(statuses.filter(x=>kind.value!=='practice'||x[0]!=='done'),previous).children);stat.value=kind.value==='practice'&&previous==='done'?'doing':previous;};form.append(field('Тип карточки',kind));icon=select([['◇','◇ Идея'],['✦','✦ Результат'],['↗','↗ Проект'],['◎','◎ Практика']],c.icon);cover=select([['soft','Мягкая цветовая обложка'],['none','Без обложки']],c.cover);form.append(field('Состояние цели',stat),field('Иконка',icon),field('Оформление',cover));}const formKey=draftKey()+':settings:';[...form.querySelectorAll('input,textarea,select')].forEach((node,i)=>keepDraft(node,formKey+i));if(kind)kind.onchange();const save=el('button','Сохранить','primary');save.type='submit';form.append(save);form.onsubmit=e=>{e.preventDefault();const v=title.value.trim();if(!v)return;if(c&&stat.value==='focus'&&c.status!=='focus'&&state.areas.flatMap(a=>a.cards).filter(x=>x.status==='focus').length>=3){notice('В фокусе уже три карточки. Сначала освободи место в одной из них.');return;}for(const key of [...drafts.keys()])if(key.startsWith(formKey))drafts.delete(key);if(s.kind==='goal'){state.title=v;state.period=period.value;}else if(c)Object.assign(c,{title:v,description:desc.value,kind:kind.value,status:kind.value==='practice'&&stat.value==='done'?'doing':stat.value,icon:icon.value,cover:cover.value});else Object.assign(d,{title:v,description:desc.value,color:color.value});panelViews.set(draftKey(),'items');render();notice('Сохранено в памяти прототипа.');};if(c&&c.title){const details=el('details');details.append(el('summary','Настроить название, описание и оформление'),form);body.append(details);}else body.append(form);if(s.kind==='area'&&d.title)body.append(button('Открыть направление →',()=>{view='area';areaIndex=s.a;render();}));if(!c)return aside;
if(c.title){body.prepend(el('p',c.icon+' '+statuses.find(x=>x[0]===c.status)[1],'saved'));if(c.description)body.append(el('p',c.description,'noteText'));}
const block=name=>{const n=el('section',undefined,'block');n.append(el('h3',name));body.append(n);return n;};
const checks=block('Небольшие шаги');for(const item of c.checklist){const row=el('div',undefined,'row'),editor=el('textarea'),check=el('input');check.type='checkbox';check.checked=item.done;check.onchange=()=>{item.done=check.checked;};check.setAttribute('aria-label','Выполнение шага: '+item.text);editor.rows=1;editor.maxLength=2000;editor.className='stepText';editor.value=item.text;editor.setAttribute('aria-label','Текст шага');editor.oninput=()=>{item.text=editor.value;check.setAttribute('aria-label','Выполнение шага: '+item.text);};row.append(check,editor,button('На доску',()=>{const task={id:uid(),title:item.text,status:item.done?'done':'todo',date:''};state.tasks.push(task);c.taskIds.push(task.id);c.checklist=c.checklist.filter(x=>x.id!==item.id);render();notice('Пункт заменён связью с задачей. Теперь выполнение хранится в карточке доски.');}),button('×',()=>{c.checklist=c.checklist.filter(x=>x.id!==item.id);render();}));checks.append(row);}addForm(checks,'Небольшой шаг','Добавить шаг',v=>c.checklist.push({id:uid(),text:v,done:false}));
const tasks=block('Связанные задачи');for(const id of c.taskIds){const t=state.tasks.find(t=>t.id===id);if(!t)continue;const row=el('div',undefined,'row');row.append(button(`${t.status==='done'?'✓':'↗'} ${t.title}`,()=>openTask(id),'linkTitle'),button('Отвязать',()=>{c.taskIds=c.taskIds.filter(x=>x!==id);render();notice('Связь убрана. Задача осталась на доске.');}));tasks.append(row);}picker(tasks,state.tasks.filter(t=>!c.taskIds.includes(t.id)),'Выбрать карточку',id=>c.taskIds.push(id));addForm(tasks,'Название новой задачи','Создать задачу',v=>{const t={id:uid(),title:v,status:'todo',date:''};state.tasks.push(t);c.taskIds.push(t.id);});
const habits=block('Поддерживающая практика');for(const id of c.habitIds){const h=state.habits.find(x=>x.id===id);if(!h)continue;const row=el('div',undefined,'row');row.append(button(`${h.history[today]?'✓':'○'} ${h.title}`,()=>{h.history[today]=!h.history[today];render();},'linkTitle'),button('Отвязать',()=>{c.habitIds=c.habitIds.filter(x=>x!==id);render();}));habits.append(row);}picker(habits,state.habits.filter(h=>!c.habitIds.includes(h.id)),'Выбрать привычку',id=>c.habitIds.push(id));
const notes=block('Заметки');addForm(notes,'Мысль, идея или вывод','Добавить заметку',v=>c.notes.push({id:uid(),text:v}),true);const settings=body.querySelector('details');if(settings)body.append(settings);return aside;}
function addForm(parent,placeholder,label,fn,multiline=false){const f=el('form',undefined,'miniForm'),n=multiline?el('textarea'):input();n.placeholder=placeholder;n.maxLength=multiline?2000:120;n.required=true;const key=draftKey()+':'+placeholder;keepDraft(n,key);const b=el('button',label);b.type='submit';f.append(n,b);f.onsubmit=e=>{e.preventDefault();const v=n.value.trim();if(v){fn(v);drafts.delete(key);render();}};parent.append(f);}
function picker(parent,items,label,fn){if(!items.length)return;const f=el('form',undefined,'miniForm'),s=select([['',label],...items.map(x=>[x.id,x.title])],'');s.required=true;const b=el('button','Привязать');b.type='submit';f.append(s,b);f.onsubmit=e=>{e.preventDefault();if(s.value){fn(s.value);render();}};parent.append(f);}
function taskButton(t){const b=button('',()=>openTask(t.id),'taskCard');b.append(el('strong',t.title),el('small',t.date||'Без даты'));const refs=linkedCards(t.id);b.append(el('small',refs.length?'Помогает: '+refs.map(x=>x.c.title).join(', '):'Пока не связана с Матрицей'));return b;}
function renderBoard(){const cols=el('div',undefined,'boardColumns');for(const [key,name] of [['todo','Запланировано'],['doing','В работе'],['done','Готово']]){const col=el('section',undefined,'column');col.append(el('h3',name));state.tasks.filter(t=>t.status===key).forEach(t=>col.append(taskButton(t)));cols.append(col);}$('content').append(el('p','Открой карточку и поменяй дату или состояние. Матрица и календарь покажут те же изменения.','sectionHint'),cols);}
function renderHabits(){const list=el('section',undefined,'habitList');for(const h of state.habits){const box=el('div',undefined,'habit');box.append(el('h3',h.title),el('p','Демонстрационная ежедневная практика'));const b=button(h.history[today]?'✓ Сегодня отмечено':'Отметить сегодня',()=>{h.history[today]=!h.history[today];render();});b.setAttribute('aria-pressed',!!h.history[today]);box.append(b);list.append(box);}$('content').append(list);}
function renderCalendar(){const list=el('div',undefined,'calendarDays'),dates=[...new Set(state.tasks.map(t=>t.date).filter(Boolean))].sort();$('content').append(el('p','Календарный список задач: даты берутся из карточек доски. Это демонстрация общей модели, не копия рабочего календаря.','sectionHint'));for(const date of dates){const day=el('section',undefined,'calendarDay');day.append(el('h3',new Date(date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})));state.tasks.filter(t=>t.date===date).forEach(t=>day.append(taskButton(t)));list.append(day);}if(!dates.length)list.append(el('p','Назначь дату задаче на доске — она появится здесь.','emptyInfo'));$('content').append(list);}
function openTask(id){editingTask=id;const t=state.tasks.find(x=>x.id===id);$('taskTitle').value=t.title;$('taskState').value=t.status;$('taskDate').value=t.date;$('taskContext').replaceChildren();for(const ref of linkedCards(id)){$('taskContext').append(button(`Помогает цели: ${ref.c.title}`,()=>{$('taskDialog').close();tab='matrix';view='area';areaIndex=state.areas.indexOf(ref.a);selected=ref.a.cards.includes(ref.c)?{kind:'card',a:areaIndex,k:ref.a.cards.indexOf(ref.c)}:{kind:'card',a:areaIndex,archiveId:ref.c.id};render();},'contextLink'));}$('taskDialog').showModal();}
$('closeTask').onclick=()=>$('taskDialog').close();$('taskForm').onsubmit=e=>{e.preventDefault();const title=$('taskTitle').value.trim();if(!title)return;Object.assign(state.tasks.find(t=>t.id===editingTask),{title,status:$('taskState').value,date:$('taskDate').value});$('taskDialog').close();render();notice('Карточка обновлена во всех представлениях.');};
$('restart').onclick=()=>{if(confirm('Начать заново? Изменения прототипа будут потеряны.'))location.reload();};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='plusyx-matrix-functional-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Снимок скачан.');};

// In-memory drafts are scoped to their original card.
const drafts=new Map();
function draftKey(){return current()?.id||state.areas[selected.a]?.id||'goal';}
function keepDraft(node,key){if(drafts.has(key))node.value=drafts.get(key);node.addEventListener('input',()=>drafts.set(key,node.value));node.addEventListener('change',()=>drafts.set(key,node.value));}
function plural(n,forms){const last=n%10,teen=n%100;return `${n} ${forms[teen>=11&&teen<=14?2:last===1?0:last>=2&&last<=4?1:2]}`;}
function cardSummary(c){
 const tasks=boardAccount?(c.boardTaskIds||[]):c.taskIds.filter(id=>state.tasks.some(t=>t.id===id));
 const habits=c.habitIds.filter(id=>state.habits.some(h=>h.id===id)).length+(c.trackerHabitIds?.length||0);
 return [[c.checklist.length,['шаг','шага','шагов']],[new Set(tasks).size,['задача','задачи','задач']],[habits,['привычка','привычки','привычек']]].filter(([n])=>n>0).map(([n,f])=>plural(n,f)).join(' · ');
}
function renderCrumbs(){const root=$('crumb');root.replaceChildren();if(tab!=='matrix')return;root.append(button('Матрица',()=>{view='home';selected={kind:'goal'};render();}));const d=state.areas[selected.a];if(d){root.append(el('span',' / '),button(d.title||'Направление',()=>{areaIndex=selected.a;view='area';selected={kind:'area',a:areaIndex};render();}));if(selected.kind==='card')root.append(el('span',' / '+(current()?.title||'Новая карточка')));}}
